/* Two pointers on a sorted array. */
int twoSumSorted(const int *a, int n, int target, int *i_out, int *j_out) {
    int i = 0, j = n - 1;
    while (i < j) {
        int s = a[i] + a[j];
        if (s == target) { *i_out = i; *j_out = j; return 1; }
        if (s < target) i++; else j--;
    }
    return 0;
}

// Go has no generic max for ints before 1.21; since 1.21 `max`/`min` are builtins.
func maxSubArray(nums []int) int {
	best, cur := nums[0], nums[0]
	for _, x := range nums[1:] {
		cur = max(x, cur+x)
		best = max(best, cur)
	}
	return best
}

// Prefix sums: O(1) range queries after O(n) setup.
func prefix(nums []int) []int {
	pre := make([]int, len(nums)+1)
	for i, x := range nums {
		pre[i+1] = pre[i] + x
	}
	return pre // sum of nums[l..r] == pre[r+1] - pre[l]
